# Import lines of name,grade,terms,contact: a person per line, in order, each added as the person form adds them.
# Every line is checked with the person form's rules before anything is written, so one refusal adds no one.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: lines
lines:
  class: net.officefloor.hq.app.person.ValidateImportPeople
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: ensure
ensure:
  class: net.officefloor.hq.app.sheet.EnsureSheet
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.person.AddImportedPeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithImportPeople
  govern: [ transaction ]
# Edit a person. Validate the body before touching the store, so a refusal writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: person
person:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: name
name:
  class: net.officefloor.hq.app.person.CheckPersonRename
  govern: [ transaction ]
  next: rollup-before
rollup-before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonEdited
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

/** How many people the import added. */
public record ImportPeopleResponse(int added) {
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * The import box's lines of name,grade,terms,contact (terms and contact may be absent or blank; blank lines are
 * skipped). Each line's fields are checked with the person form's rules; a name (ignoring case) or contact repeated
 * within the import refuses it. A refusal names the line. Publishes them parsed, in order, with the user making the
 * change.
 */
public class ValidateImportPeople {

    static final int MAX_LINES = 1000;

    public void validate(@RequestBody ImportPeopleRequest request, Out<ImportedPeople> imported,
            Out<ChangedBy> changedBy) throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String text = request == null || request.lines() == null ? "" : request.lines();
        List<PersonRequest> people = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        String[] typed = text.split("\\r?\\n");
        for (int i = 0; i < typed.length; i++) {
            if (typed[i].trim().isEmpty()) {
                continue;
            }
            String[] fields = typed[i].split(",", -1);
            if (fields.length < 2 || fields.length > 4) {
                throw new BadRequestException("Line " + (i + 1) + ": enter name,grade,terms,contact");
            }
            try {
                PersonRequest person = ValidatePerson.parse(new PersonRequest(fields[0], fields[1], by.name(), null,
                        "", fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : ""), by);
                if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                    throw new BadRequestException(person.name() + " is repeated in the import");
                }
                if (person.contactOrNull() != null && !contacts.add(person.contact())) {
                    throw new BadRequestException("The contact " + person.contact() + " is repeated in the import");
                }
                people.add(person);
            } catch (BadRequestException e) {
                throw new BadRequestException("Line " + (i + 1) + ": " + e.getMessage());
            }
        }
        if (people.isEmpty()) {
            throw new BadRequestException("Paste at least one line of name,grade,terms,contact");
        }
        if (people.size() > MAX_LINES) {
            throw new BadRequestException("Import at most " + MAX_LINES + " lines at once");
        }
        imported.set(new ImportedPeople(people));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupSnapshot;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Adds a person per imported line, in order. Every line is first checked as the person form checks a new person
 * (name or alias in use on the sheet or its tree, contact another person's); one refusal refuses them all before
 * anything is written. Each is then added as the form adds them: PERSON_ADDED, then the rollup lines it moved.
 */
public class AddImportedPeople {

    public void add(@Val SheetResponse sheet, @Val ImportedPeople imported, @Val ChangedBy by,
            PersonRepository repository, Rollup rollup, Audit audit, Out<ImportPeopleResponse> response)
            throws BadRequestException {
        int n = 0;
        for (PersonRequest request : imported.people()) {
            n++;
            if (repository.nameTaken(sheet.id(), request.name(), null)) {
                throw new BadRequestException("Line " + n + ": " + PersonRepository.NAME_TAKEN);
            }
            if (repository.contactTaken(sheet.id(), request.contactOrNull(), null)) {
                throw new BadRequestException("Line " + n + ": " + PersonRepository.CONTACT_TAKEN);
            }
        }
        for (PersonRequest request : imported.people()) {
            RollupSnapshot before = rollup.snapshot(sheet.id());
            Person person = repository.insert(sheet.id(), request.name(), request.grade(), request.termsDays(),
                    request.contactOrNull());
            new RecordPersonAdded().record(person, by, audit);
            rollup.record(sheet.id(), before, by);
        }
        response.set(new ImportPeopleResponse(imported.people().size()));
    }
